){margin:.5em auto 1em;max-width:13em}.wh-share-qr{width:13em;height:13em;max-width:100%;display:block;margin:auto}.wh-share-save{display:block;margin:1.3em auto 0!important;width:55%}.wh-dialog-share{padding:0;background:transparent;overflow:visible;max-width:22em}.wh-dialog-share>.wh-dialog-head{display:none}.wh-dialog-share::after{content:none}.wh-promotion-overlay{align-items:flex-end;padding:0}.wh-dialog-promotion{background:linear-gradient(132deg,#36312f,#1c1918 68%);border-radius:1.25em 1.25em 0 0;max-width:750px;padding:1.35em 1.7em calc(1.4em + env(safe-area-inset-bottom));color:#f0d6b9}.wh-dialog-promotion>.wh-dialog-head{font-size:1.38em;font-weight:600;padding:.05em 2.2em 1.65em;color:#fff}.wh-dialog-promotion>.wh-dialog-head .wh-close{right:.1em;top:.05em}.wh-dialog-promotion>.wh-dialog-head .wh-close image{width:1.5em;height:1.5em}.wh-promotion-compare{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.12fr);align-items:center;position:relative;margin:.2em 0 1.35em}.wh-promotion-before,.wh-promotion-after{position:relative;box-sizing:border-box;min-height:8.9em;text-align:center;font-size:.86em;display:flex;flex-direction:column;align-items:center}.wh-promotion-before{z-index:1;color:#bc5135;background:linear-gradient(112deg,#ffeddc,#ffc292);border-radius:1.18em;padding:2.3em .45em 1em}.wh-promotion-before::after{content:'';position:absolute;right:-.65em;bottom:.72em;width:1.25em;height:1.25em;border-radius:50%;background:#201b19}.wh-promotion-after{z-index:2;margin-left:-.2em;border:1rpx solid #ebc29f;border-radius:1.2em;color:#cbb299;background:linear-gradient(130deg,#2a2421,#1c1918);padding:2.25em .5em 1em;box-shadow:-.22em 0 .95em #eab59455}.wh-promotion-stage{position:absolute;top:0;min-width:4.6em;padding:.4em .7em .5em;border-radius:0 0 .85em .85em;font-size:1.12em;font-weight:700;line-height:1.15}.wh-promotion-before .wh-promotion-stage{background:#ffcfaa}.wh-promotion-after .wh-promotion-stage{background:#ffdfbf;color:#5c2a00}.wh-promotion-level{min-height:2.2em;display:flex;align-items:center;justify-content:center;font-size:1.38em;font-weight:700;line-height:1.2;overflow-wrap:anywhere}.wh-promotion-after .wh-promotion-level{color:#f9e9db;font-size:1.57em}.wh-promotion-divider{width:100%;height:1rpx;margin:.85em 0 .8em;background:repeating-linear-gradient(90deg,#ebc19d 0 .35em,transparent .35em .7em);opacity:.7}.wh-promotion-after .wh-promotion-divider{background:repeating-linear-gradient(90deg,#61534b 0 .35em,transparent .35em .7em)}.wh-promotion-arrow{position:absolute;z-index:3;left:42.8%;bottom:-.26em;width:2.6em;height:2.8em;background:linear-gradient(135deg,#ffbd6b,#ff6c26);clip-path:polygon(50% 0,100% 47%,72% 47%,72% 100%,28% 100%,28% 47%,0 47%);filter:drop-shadow(0 .3em .38em #ff8b3d88)}.wh-promotion-arrow::after{content:'';position:absolute;inset:.14em;background:linear-gradient(135deg,#ffcc8f,#ff7c32);clip-path:inherit}.wh-promotion-switch{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1em;margin-bottom:1.2em}.wh-promotion-switch button{min-width:0;margin:0;padding:.55em .35em;border-radius:3em;background:#ffffff1f;color:#ffffffb8;line-height:1.35;font-size:.98em}.wh-promotion-switch button.active{color:#5c2a00;background:linear-gradient(105deg,#ffe5c6,#f3b56f);font-weight:600}.wh-promotion-note{margin:0 0 1em;border:1rpx solid #eec39d;border-radius:.55em;padding:.75em .85em;color:#cab29b;font-size:.94em;line-height:1.55;background:linear-gradient(110deg,#3f3630,#191617)}.wh-price-lines{overflow:hidden;background:#3a3432;border-radius:.42em;padding:0;font-size:1em}.wh-price-lines>view{display:flex;justify-content:space-between;gap:1em;padding:.72em .85em;border-bottom:1rpx solid #524a46}.wh-price-lines>view:nth-child(odd){background:#5b5350}.wh-price-lines>view:last-child{border:0}.wh-price-lines text:first-child{color:#ffffffb8}.wh-price-lines text:last-child{color:#fff;white-space:nowrap}.wh-promotion-progress{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1em;margin:1.7em auto .2em;max-width:17em;text-align:center;font-size:1.05em;color:#ffffffc7}.wh-promotion-progress>view>text{display:block}.wh-promotion-progress>view>view{margin-top:.35em;color:#f8d3b3;font-size:1.8em;font-weight:700;line-height:1.15}.wh-dialog-superior>.wh-dialog-head{display:none}
